 {edgeId:'observed-exposure',status:'EXECUTABLE_MODEL_RELATION',label:{en:'Executable model relation',ro:'Relație executabilă în model'},explanation:{en:'Observed claim events are registered as exposures in the reference mechanism.',ro:'Evenimentele observate ale unei afirmații sunt înregistrate drept expuneri în mecanismul de referință.'}},
 {edgeId:'exposure-familiarity',status:'EMPIRICAL_CAUSAL_SUPPORT',label:{en:'Empirical causal support',ro:'Suport cauzal empiric'},explanation:{en:'Repeated exposure is experimentally manipulated and reliably changes later truth judgments; familiarity is the registered candidate mediator.',ro:'Expunerea repetată este manipulată experimental și modifică fiabil judecățile ulterioare de adevăr; familiaritatea este mediatorul candidat înregistrat.'}},
 {edgeId:'familiarity-belief',status:'EMPIRICAL_ASSOCIATION',label:{en:'Empirical association',ro:'Asociere empirică'},explanation:{en:'The phenomenon supports a familiarity/plausibility bridge, but the specific latent-state mediation is not uniquely identified by the meta-analysis.',ro:'Fenomenul susține o legătură familiaritate/plauzibilitate, dar medierea prin starea latentă specifică nu este identificată unic de meta-analiză.'}},
 {edgeId:'correction-belief',status:'EMPIRICAL_CAUSAL_SUPPORT',label:{en:'Empirical causal support',ro:'Suport cauzal empiric'},explanation:{en:'Randomized correction/debunking studies measure downstream belief change, with substantial domain dependence.',ro:'Studiile randomizate de corecție/debunking măsoară schimbarea ulterioară a convingerii, cu dependență importantă de domeniu.'}},
 {edgeId:'correction-reassessment',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'CEM represents correction as a possible trigger for reassessment; no single universal descriptive equation is claimed.',ro:'CEM reprezintă corecția drept posibil declanșator al reevaluării; nu revendică o ecuație descriptivă universală.'}},
 {edgeId:'observed-appraisal',status:'EMPIRICAL_CAUSAL_SUPPORT',label:{en:'Empirical causal support',ro:'Suport cauzal empiric'},explanation:{en:'Randomized information-emphasis manipulations can change downstream evaluations, while the CEM state is a model proxy.',ro:'Manipulările randomizate ale accentului informațional pot schimba evaluările ulterioare, în timp ce starea CEM este un proxy de model.'}},
 {edgeId:'observed-world',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Observed information is treated as an input to internal representation; the descriptive cognitive implementation remains task-dependent.',ro:'Informația observată este tratată drept intrare în reprezentarea internă; implementarea cognitivă descriptivă rămâne dependentă de sarcină.'}},
 {edgeId:'memory-world',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Prior information and memory constrain representation, without assuming a single universal memory-to-belief function.',ro:'Informația anterioară și memoria constrâng reprezentarea, fără a presupune o funcție universală memorie–convingere.'}},
 {edgeId:'source-diagnosticity',status:'INTERPRETIVE_LINK',label:{en:'Interpretive link',ro:'Legătură interpretativă'},explanation:{en:'Source credibility and evidence diagnosticity are distinct constructs; CEM does not provide a validated universal conversion between them.',ro:'Credibilitatea sursei și diagnosticitatea dovezii sunt constructe distincte; CEM nu oferă o conversie universală validată între ele.'}},
 {edgeId:'social-world',status:'INTERPRETIVE_LINK',label:{en:'Interpretive link',ro:'Legătură interpretativă'},explanation:{en:'Social context can shape interpretation, but generic consensus is not treated as independent evidence or a universal causal coefficient.',ro:'Contextul social poate modela interpretarea, dar consensul generic nu este tratat drept dovadă independentă sau coeficient cauzal universal.'}},
 {edgeId:'diagnosticity-world',status:'NORMATIVE_OPERATOR',label:{en:'Normative operator',ro:'Operator normativ'},explanation:{en:'When a defensible likelihood ratio and prior exist, Bayesian updating specifies how evidence should update probability; it is not a descriptive claim that humans compute this way.',ro:'Când există un likelihood ratio și un prior justificabile, actualizarea bayesiană specifică modul normativ de actualizare a probabilității; nu afirmă că oamenii calculează astfel.'}},
 {edgeId:'world-uncertainty',status:'NORMATIVE_OPERATOR',label:{en:'Normative operator',ro:'Operator normativ'},explanation:{en:'Uncertainty can be derived from a probability representation; this is a mathematical operator, not a psychological causal claim.',ro:'Incertitudinea poate fi derivată dintr-o reprezentare probabilistică; este un operator matematic, nu o afirmație cauzală psihologică.'}},
 {edgeId:'world-reassessment',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Internal representations remain revisable when contradiction or new information appears.',ro:'Reprezentările interne rămân revizuibile când apare contradicție sau informație nouă.'}},
 {edgeId:'reassessment-memory',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Reassessment is represented as changing the context available to later cycles.',ro:'Reevaluarea este reprezentată ca modificând contextul disponibil ciclurilor ulterioare.'}},
 {edgeId:'belief-judgment',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Belief-related state can contribute to judgment, but observed judgment does not uniquely identify the internal state that produced it.',ro:'Starea legată de convingere poate contribui la judecată, dar judecata observată nu identifică unic starea internă care a produs-o.'}},
 {edgeId:'appraisal-judgment',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'Appraisal is represented as one contributor to judgment rather than a complete causal account.',ro:'Evaluarea este reprezentată drept unul dintre factorii care contribuie la judecată, nu drept explicație cauzală completă.'}},
 {edgeId:'belief-action',status:'EXECUTABLE_MODEL_RELATION',label:{en:'Executable model relation',ro:'Relație executabilă în model'},explanation:{en:'The reference action policy uses belief-related state as one input; the coefficients are not population-calibrated.',ro:'Politica de acțiune de referință folosește starea legată de convingere drept una dintre intrări; coeficienții nu sunt calibrați populațional.'}},
 {edgeId:'accuracy-action',status:'EXECUTABLE_MODEL_RELATION',label:{en:'Executable model relation',ro:'Relație executabilă în model'},explanation:{en:'The reference action policy includes accuracy weighting; experiments support accuracy-prompt effects on sharing but do not directly identify the model state.',ro:'Politica de acțiune de referință include ponderea acurateții; experimentele susțin efecte ale accuracy prompts asupra distribuirii, dar nu identifică direct starea modelului.'}},
 {edgeId:'judgment-action',status:'CONCEPTUAL_HYPOTHESIS',label:{en:'Conceptual hypothesis',ro:'Ipoteză conceptuală'},explanation:{en:'A judgment can precede action, but action is not treated as a transparent readout of belief or endorsement.',ro:'O judecată poate preceda acțiunea, dar acțiunea nu este tratată drept reflectare transparentă a convingerii sau aprobării.'}}
