 {nodeId:'familiarity',strength:{en:'Strong phenomenon-level empirical support; small average effect with substantial heterogeneity.',ro:'Suport empiric puternic la nivel de fenomen; efect mediu mic, cu eterogenitate substanțială.'},studyType:{en:'Systematic review and three-level meta-analysis of experimental studies.',ro:'Revizuire sistematică și meta-analiză pe trei niveluri a studiilor experimentale.'},studies:{en:'182 studies, 366 effect sizes, 99 reports.',ro:'182 studii, 366 mărimi de efect, 99 rapoarte.'},populations:{en:'31,184 participants; studies published 1977–2025, predominantly Europe and North America.',ro:'31.184 participanți; studii publicate 1977–2025, predominant în Europa și America de Nord.'},effectSize:{en:'Small-study-adjusted pooled illusory-truth effect: g=0.37, 95% CI 0.30–0.44.',ro:'Efect agregat de adevăr iluzoriu corectat pentru small-study effects: g=0,37, IC95% 0,30–0,44.'},uncertainty:{en:'Sensitivity analyses produced similar small-to-moderate estimates; the pooled estimate is not an individual probability.',ro:'Analizele de sensibilitate au produs estimări mici–moderate similare; estimarea agregată nu este probabilitate individuală.'},heterogeneity:{en:'Substantial within- and between-study heterogeneity.',ro:'Eterogenitate substanțială intra- și inter-studiu.'},moderators:{en:'Item type, first-exposure instructions, veracity cues and initial exposure duration explained part of the heterogeneity.',ro:'Tipul itemului, instrucțiunile la prima expunere, indiciile de veridicitate și durata expunerii inițiale au explicat o parte din eterogenitate.'},quality:{en:'Risk-of-bias assessment found most studies raised some concerns, especially lack of preregistration; the meta-analysis corrected for small-study effects.',ro:'Evaluarea riscului de bias a indicat unele preocupări pentru majoritatea studiilor, în special lipsa preregistrării; meta-analiza a corectat small-study effects.'},replication:{en:'The phenomenon has been reproduced across decades and many experimental contexts.',ro:'Fenomenul a fost reprodus de-a lungul mai multor decenii și contexte experimentale.'},competing:{en:'Processing fluency and referential-memory accounts are plausible and need not be mutually exclusive.',ro:'Explicațiile prin processing fluency și memoria referențială sunt plauzibile și nu trebuie să fie mutual exclusive.'},limitations:{en:'The pooled repetition effect cannot be converted into a personal susceptibility score or directly into a CEM latent-state coefficient.',ro:'Efectul agregat al repetiției nu poate fi transformat într-un scor personal de susceptibilitate sau direct într-un coeficient al stării latente CEM.'},sources:[{label:'Ye et al., Nature Communications (2026)',url:'https://www.nature.com/articles/s41467-026-70041-x'}]},
 {nodeId:'correction',strength:{en:'Large literature, but average effectiveness depends strongly on domain and design.',ro:'Literatură extinsă, dar eficacitatea medie depinde puternic de domeniu și design.'},studyType:{en:'Meta-analysis of science-relevant misinformation corrections plus broader correction literature.',ro:'Meta-analiză a corecțiilor pentru misinformation relevantă științific plus literatura mai largă despre corecții.'},studies:{en:'75 reports, 245 effect sizes in the 2023 science-relevant misinformation meta-analysis.',ro:'75 rapoarte, 245 mărimi de efect în meta-analiza din 2023 privind misinformation relevantă științific.'},populations:{en:'53,320 participants across science-relevant misinformation studies.',ro:'53.320 participanți în studii privind misinformation relevantă științific.'},effectSize:{en:'Average debunking effect in that synthesis: d=0.11, 95% CI −0.04 to 0.26; not statistically distinguishable from zero.',ro:'Efectul mediu de debunking în acea sinteză: d=0,11, IC95% −0,04–0,26; nedistinct statistic de zero.'},uncertainty:{en:'The null average masks meaningful conditional differences; it should not be generalized to all correction formats.',ro:'Media nulă maschează diferențe condiționale relevante; nu trebuie generalizată la toate formatele de corecție.'},heterogeneity:{en:'Effectiveness varies materially across topic and context.',ro:'Eficacitatea variază substanțial între subiecte și contexte.'},moderators:{en:'Corrections were more successful for negative topics, domains other than health, less politically polarized issues and when recipients were familiar with competing positions.',ro:'Corecțiile au avut mai mult succes pentru subiecte negative, domenii altele decât sănătatea, teme mai puțin polarizate politic și când participanții cunoșteau pozițiile concurente.'},quality:{en:'Meta-analytic evidence is broad, but outcome definitions and misinformation domains differ across studies.',ro:'Dovezile meta-analitice sunt extinse, dar definițiile outcome-urilor și domeniile misinformation diferă între studii.'},replication:{en:'Correction effects are repeatedly observed, but size and persistence are not uniform.',ro:'Efectele corecțiilor sunt observate repetat, dar mărimea și persistența nu sunt uniforme.'},competing:{en:'Continued influence may reflect retrieval competition, gaps in mental models, source/retraction processing or motivated/contextual factors.',ro:'Influența persistentă poate reflecta competiția la reactualizare, goluri în modelele mentale, procesarea sursei/retractării sau factori motivaționali/contextuali.'},limitations:{en:'CEM cannot infer that one correction will reverse one person’s belief, nor treat accessibility as a universal correction coefficient.',ro:'CEM nu poate deduce că o corecție va inversa convingerea unei persoane și nici trata accesibilitatea drept coeficient universal al corecției.'},sources:[{label:'Chan & Albarracín, Nature Human Behaviour (2023)',url:'https://www.nature.com/articles/s41562-023-01623-8'},{label:'Kozyreva et al., Nature Human Behaviour (2024)',url:toolbox.url}]},
 {nodeId:'accuracy-weighting',strength:{en:'Replicated experimental support for sharing discernment; the intervention does not directly measure the CEM internal state.',ro:'Suport experimental replicat pentru discernământul la distribuire; intervenția nu măsoară direct starea internă CEM.'},studyType:{en:'Internal random-effects meta-analysis of randomized online experiments.',ro:'Meta-analiză internă cu efecte aleatoare a experimentelor online randomizate.'},studies:{en:'20 experiments.',ro:'20 de experimente.'},populations:{en:'26,863 U.S. social-media users in online survey samples, 2017–2020.',ro:'26.863 utilizatori de social media din SUA în eșantioane de sondaj online, 2017–2020.'},effectSize:{en:'Accuracy prompts increased sharing discernment (b=0.038) and reduced false-headline sharing intentions by about 10% relative to control.',ro:'Accuracy prompts au crescut discernământul la distribuire (b=0,038) și au redus cu aproximativ 10% intențiile de distribuire a titlurilor false față de control.'},uncertainty:{en:'The studies primarily measured sharing intentions; field behavior and longer-term durability are less directly established by this synthesis.',ro:'Studiile au măsurat în principal intenții de distribuire; comportamentul de teren și durabilitatea pe termen lung sunt mai puțin direct stabilite de această sinteză.'},heterogeneity:{en:'Sharing-discernment effects were heterogeneous (I²=78.5%); false-headline sharing effects had much lower heterogeneity (I²=18.5%).',ro:'Efectele asupra discernământului la distribuire au fost eterogene (I²=78,5%); efectele asupra distribuirii titlurilor false au avut eterogenitate mult mai mică (I²=18,5%).'},moderators:{en:'Effects were larger among older, more reflective and more attentive participants; no robust moderation by several demographic and ideological measures.',ro:'Efectele au fost mai mari la participanți mai în vârstă, mai reflexivi și mai atenți; nu s-a observat moderare robustă pentru mai multe caracteristici demografice și ideologice.'},quality:{en:'All relevant experiments from the research group were included, but this is an internal meta-analysis rather than a field-wide systematic review.',ro:'Au fost incluse toate experimentele relevante ale grupului de cercetare, dar aceasta este o meta-analiză internă, nu o revizuire sistematică a întregului domeniu.'},replication:{en:'The effect replicated across multiple prompt implementations and content sets in the included experiments.',ro:'Efectul s-a replicat pentru mai multe implementări de prompt și seturi de conținut în experimentele incluse.'},competing:{en:'Attention-to-accuracy accounts fit the intervention, but sharing can also be shaped by social goals, incentives and platform context.',ro:'Explicația prin orientarea atenției spre acuratețe se potrivește intervenției, dar distribuirea poate fi modelată și de obiective sociale, stimulente și contextul platformei.'},limitations:{en:'A prompt effect on sharing does not prove that belief changed and cannot be interpreted as a personal accuracy trait.',ro:'Un efect al promptului asupra distribuirii nu dovedește că s-a schimbat convingerea și nu poate fi interpretat drept trăsătură personală de acuratețe.'},sources:[{label:'Pennycook & Rand, Nature Communications (2022)',url:'https://www.nature.com/articles/s41467-022-30073-5'}]},
 {nodeId:'source-provenance',strength:{en:'Empirical support that source-credibility cues can affect truth discernment; no universal source-to-truth conversion exists.',ro:'Suport empiric că indiciile de credibilitate a sursei pot afecta discernământul adevărului; nu există o conversie universală sursă–adevăr.'},studyType:{en:'Randomized social-media simulation plus broader source-monitoring literature.',ro:'Simulare randomizată de social media plus literatura mai largă despre source monitoring.'},studies:{en:'One directly relevant 2024 experiment in the intervention catalog; broader source-monitoring evidence spans many paradigms.',ro:'Un experiment direct relevant din 2024 în catalogul de intervenții; dovezile mai largi de source monitoring acoperă numeroase paradigme.'},populations:{en:'N=415 adults in a social-media simulation for the 2024 credibility-badge/social-norm study.',ro:'N=415 adulți într-o simulare de social media pentru studiul din 2024 privind credibility badges și norme sociale.'},uncertainty:{en:'Effects depend on cue validity, trust, task and prior knowledge.',ro:'Efectele depind de validitatea indiciilor, încredere, sarcină și cunoașterea anterioară.'},heterogeneity:{en:'No field-wide pooled estimate is attached to this mechanism in CEM.',ro:'CEM nu atașează acestui mecanism o estimare agregată la nivelul întregului domeniu.'},moderators:{en:'Source trust and cue credibility are plausible moderators; warning-label effects are smaller among people who distrust fact-checkers.',ro:'Încrederea în sursă și credibilitatea indiciului sunt moderatori plauzibili; efectele warning labels sunt mai mici la persoanele care nu au încredere în fact-checkers.'},quality:{en:'Direct intervention evidence is experimental but not sufficient for a universal source-reliability coefficient.',ro:'Dovezile directe de intervenție sunt experimentale, dar insuficiente pentru un coeficient universal de fiabilitate a sursei.'},replication:{en:'Source-cue effects recur across literatures, but operationalizations differ substantially.',ro:'Efectele indiciilor despre sursă reapar în literaturi diferite, dar operaționalizările diferă substanțial.'},competing:{en:'Source cues may operate through learned reliability, authority heuristics, familiarity or social trust.',ro:'Indiciile despre sursă pot opera prin fiabilitate învățată, euristici de autoritate, familiaritate sau încredere socială.'},limitations:{en:'CEM does not infer actual truth from source reputation and does not convert a credibility label into a likelihood ratio automatically.',ro:'CEM nu deduce adevărul real din reputația sursei și nu transformă automat o etichetă de credibilitate într-un likelihood ratio.'},sources:[{label:'Prike, Butler & Ecker, Scientific Reports (2024)',url:'https://www.nature.com/articles/s41598-024-57560-7'},{label:'Martel & Rand, Nature Human Behaviour (2024)',url:'https://www.nature.com/articles/s41562-024-01973-x'}]},
 {nodeId:'social-context',strength:{en:'Experimental support exists for some norm interventions, but generic social influence remains highly context dependent.',ro:'Există suport experimental pentru unele intervenții bazate pe norme, dar influența socială generică rămâne puternic dependentă de context.'},studyType:{en:'Randomized social-media simulation plus intervention review.',ro:'Simulare randomizată de social media plus revizuire a intervențiilor.'},studies:{en:'A 2024 randomized experiment (N=415) directly compared social-norm and credibility-badge interventions; the 2024 toolbox reviews the broader intervention class.',ro:'Un experiment randomizat din 2024 (N=415) a comparat direct intervențiile bazate pe norme sociale și credibility badges; toolbox-ul din 2024 revizuiește clasa mai largă.'},populations:{en:'Adult online participants in simulated social-media contexts; broader intervention studies span multiple countries.',ro:'Participanți adulți online în contexte simulate de social media; studiile mai largi de intervenție acoperă mai multe țări.'},uncertainty:{en:'Some engagement effects in the norm study were not robust to alternative specifications.',ro:'Unele efecte asupra engagement-ului în studiul normelor nu au fost robuste la specificații alternative.'},heterogeneity:{en:'No single pooled social-norm effect is used in CEM.',ro:'CEM nu folosește un singur efect agregat al normelor sociale.'},moderators:{en:'Norm salience, reference group, platform context and baseline behavior can plausibly moderate effects.',ro:'Saliența normei, grupul de referință, contextul platformei și comportamentul inițial pot modera plauzibil efectele.'},quality:{en:'Direct experimental evidence is useful but still narrow relative to the breadth of “social influence”.',ro:'Dovezile experimentale directe sunt utile, dar încă înguste față de amploarea conceptului de „influență socială”.'},replication:{en:'The broader intervention literature contains multiple norm studies, but implementations are not interchangeable.',ro:'Literatura mai largă de intervenție conține mai multe studii despre norme, dar implementările nu sunt interschimbabile.'},competing:{en:'Observed norm effects can reflect conformity, information about others, reputational incentives or attention shifts.',ro:'Efectele observate ale normelor pot reflecta conformism, informații despre ceilalți, stimulente reputaționale sau schimbări ale atenției.'},limitations:{en:'CEM does not infer an individual conformity trait or treat popularity as evidence of truth.',ro:'CEM nu deduce o trăsătură individuală de conformism și nu tratează popularitatea drept dovadă a adevărului.'},sources:[{label:'Prike, Butler & Ecker, Scientific Reports (2024)',url:'https://www.nature.com/articles/s41598-024-57560-7'},{label:toolbox.label,url:toolbox.url}]}
