export const edgeEvidenceFor=(edgeId:string)=>edgeEvidence.find(item=>item.edgeId===edgeId);
export const evidenceForNode=(nodeId:string)=>mechanismEvidence.find(item=>item.nodeId===nodeId);
export const pathwayById=(id:string|undefined|null)=>questionPathways.find(item=>item.id===id);
export const intersections=(a:string[],b:string[])=>a.some(item=>b.includes(item));
export const epistemicOrder:EpistemicLevel[]=['EMPIRICAL','EXECUTABLE','CONCEPTUAL','INTERPRETIVE'];
